import type { DateTime } from 'luxon'
import type { Month } from '#domain/calendar/month'
import { insightPeriodKey } from '#domain/insights/monthly_schedule'

/**
 * Which written monthly summaries get a "your summary is ready" push, and
 * who gets it. Pure.
 */

export interface WrittenSummary {
  month: Month
  generatedAt: DateTime
  /** Who tapped Generate; null when the scheduler (or `insights:generate`) wrote it. */
  generatedByUserId: number | null
}

/**
 * A scheduled summary always is. One a member generated by hand only when it
 * is the month that had just ended when it was written (household time
 * zone): a summary of the current month (it covers part of it, the scheduled
 * one replaces it) or of an older month (someone browsing history) is news
 * to nobody.
 */
export function isAnnounceable(summary: WrittenSummary, zone: string): boolean {
  if (summary.generatedByUserId === null) return true
  return summary.month === insightPeriodKey(summary.generatedAt, zone)
}

/** Every member but the one who generated it by hand (they saw it on screen). */
export function recipientsOf(memberIds: number[], generatedByUserId: number | null): number[] {
  return memberIds.filter((id) => id !== generatedByUserId)
}
